import openpyxl
p='/tmp/llm_rollout__5a61icz/seed_collection_0017_relative_vs_absolute_references_2827_input.xlsx'
wb=openpyxl.load_workbook(p, data_only=False)
for sheet in ['2002 Plan','2001 Forecast']:
    ws=wb[sheet]
    print('\n===',sheet,'rows 46-52 ===')
    for r in range(44, 53):
        vals=[]
        for c in range(1, ws.max_column+1):
            v=ws.cell(r,c).value
            if v is not None:
                vals.append(f'{ws.cell(r,c).coordinate}={v!r}')
        if vals:
            print('ROW',r, ' | '.join(vals))
